     CROSS JOIN LATERAL ( WITH comparable AS (
                 SELECT o.id,
                    o.tenant_id,
                    o.product_id,
                    o.price_cents,
                    o.original_price_cents,
                    o.claimed_discount_rate,
                    o.observed_at,
                    o.rating_star,
                    o.sales_label,
                    o.sales_count,
                    o.capture_run_id,
                    o.title_snapshot,
                    o.product_url_snapshot,
                    o.image_url_snapshot,
