create policy "extension_device_read" on garimpa."extension_device" for select to garimpa_app using(exists(select 1 from garimpa.affiliate_account a where a.id=affiliate_id and a.tenant_id=nullif(current_setting('garimpa.tenant_id',true),'')));
create policy "extension_device_manage" on garimpa."extension_device" for all to garimpa_app using(exists(select 1 from garimpa.affiliate_account a where a.id=affiliate_id and a.tenant_id=nullif(current_setting('garimpa.tenant_id',true),'')) and current_setting('garimpa.membership_role',true)='owner') with check(exists(select 1 from garimpa.affiliate_account a where a.id=affiliate_id and a.tenant_id=nullif(current_setting('garimpa.tenant_id',true),'')) and current_setting('garimpa.membership_role',true)='owner');
create policy app_user_role_runtime_read on garimpa.app_user_role for select to garimpa_app using(app_user_id=nullif(current_setting('garimpa.actor_app_user_id',true),''));
grant execute on function garimpa.accept_account_invitation(text,text,text,text) to garimpa_app;
do $state$ declare affected integer; begin
 update garimpa.rollout_control set enabled=true where id='bizuminer-v2' and not enabled;
 get diagnostics affected=row_count;
 if affected<>1 or not garimpa.commercial_rollout_ready() then raise exception 'rollout_activation_failed'; end if;
end $state$;
